BATCH: dict[str, dict[str, Any]] = {'Seneca': {'hint': 'فيلسوف رواقي وكاتب لاتيني ارتبط اسمه بفلسفة ضبط النفس وبلاط الإمبراطور نيرون.', 'bio': 'كان سينيكا الأصغر فيلسوفاً رواقياً وكاتباً ومسرحياً رومانياً في القرن الأول الميلادي. عمل مستشاراً لنيرون في بداية حكمه، ثم ابتعد عن الحياة السياسية قبل أن يُجبر على الانتحار سنة 65م بعد اتهامه بالمشاركة في مؤامرة بيزو.', 'achievements': ['كتب رسائل فلسفية تناولت الفضيلة والغضب وقصر الحياة والسعادة.', 'ألّف مآسي لاتينية مؤثرة مثل «ميديا» و«فدرا».', 'كان من أبرز المعبّرين عن الفلسفة الرواقية في الأدب اللاتيني.'], 'key_facts': ['وُلد نحو 4 ق.م. وتوفي سنة 65م.', 'كان معلماً ومستشاراً للإمبراطور نيرون.', 'تنسب إليه رسائل أخلاقية ومؤلفات فلسفية ومسرحية واسعة التأثير.'], 'wars': [], 'historical_significance': 'أسهم سينيكا في نقل الأفكار الرواقية إلى الأدب اللاتيني، وظلت كتاباته الأخلاقية مؤثرة في الفكر الأوروبي اللاحق.'}, 'Ovid': {'hint': 'شاعر روماني اشتهر بـ«التحولات» وبقصائده عن الحب والأساطير.', 'bio': 'كان أوفيد من أبرز شعراء العصر الذهبي للأدب اللاتيني. اشتهر بكتاب «التحولات» الذي جمع أساطير يونانية ورومانية في قصيدة طويلة، ونُفي من روما بأمر أغسطس إلى توميس على البحر الأسود.', 'achievements': ['ألّف «التحولات»، أحد أهم الأعمال الشعرية في التراث الكلاسيكي.', 'كتب «فن الحب» وأعمالاً شعرية تناولت الحب والأساطير.', 'أثر في الأدب الأوروبي الوسيط والنهضوي عبر إعادة سرد الأساطير الكلاسيكية.'], 'key_facts': ['وُلد سنة 43 ق.م. وتوفي نحو 17 أو 18م.', 'نُفي إلى توميس سنة 8م.', 'كان من معاصري فيرجيل وهوراس في العصر الأدبي الأوغسطي.'], 'wars': [], 'historical_significance': 'تُعد «التحولات» مصدراً أدبياً أساسياً لتلقي الأساطير الكلاسيكية، وكان لأوفيد تأثير واسع في الشعر والفنون الأوروبية.'}, 'Trajan': {'hint': 'إمبراطور روماني بلغت الإمبراطورية في عهده أقصى اتساع إقليمي لها.', 'bio': 'كان تراجان إمبراطوراً رومانياً حكم من 98 إلى 117م. قاد حملات ناجحة ضد الداقيين والبارثيين، واشتهر أيضاً ببرامج البناء العامة وبعمود تراجان في روما.', 'achievements': ['هزم مملكة داقية وضم أراضيها إلى الإمبراطورية.', 'قاد الحرب ضد البارثيين ووسع النفوذ الروماني شرقاً.', 'أنشأ منتدى تراجان ومشروعات عمرانية كبرى في روما.'], 'key_facts': ['حكم بين 98 و117م.', 'كان أول إمبراطور روماني من أصول إقليمية غير إيطالية.', 'بلغت الإمبراطورية أقصى اتساعها الجغرافي تقريباً في عهده.'], 'wars': ['الحرب الداقية (101–102م)', 'الحرب الداقية الثانية (105–106م)', 'الحرب البارثية (114–117م)'], 'historical_significance': 'يمثل عهد تراجان ذروة التوسع الإقليمي الروماني، وأصبح نموذجاً للإمبراطور المنتصر في الذاكرة السياسية الرومانية.'}, 'Virgil': {'hint': 'شاعر روماني كتب «الإنيادة» التي جعلت تأسيس روما ملحمة شعرية كبرى.', 'bio': 'كان فيرجيل شاعراً لاتينياً عاش في القرن الأول قبل الميلاد، واشتهر بثلاثة أعمال كبرى هي «القصائد الرعوية» و«الزراعيات» و«الإنيادة». أصبحت الإنيادة ملحمة مركزية في الأدب اللاتيني وربطت أسطورة أينياز بتاريخ روما.', 'achievements': ['ألّف «الإنيادة»، الملحمة القومية الأشهر في الأدب اللاتيني.', 'كتب «الزراعيات» التي جمعت الشعر بالتأمل في الزراعة والطبيعة.', 'أرسى نموذجاً شعرياً أثر في دانتي وشعراء أوروبيين كثيرين.'], 'key_facts': ['وُلد سنة 70 ق.م. وتوفي سنة 19 ق.م.', 'تدور «الإنيادة» حول البطل أينياز وأصول الرومان الأسطورية.', 'لم يُكمل مراجعة الإنيادة قبل وفاته.'], 'wars': [], 'historical_significance': 'كانت «الإنيادة» من أهم النصوص التي شكّلت صورة روما عن أصولها، وأصبحت أساساً لتقاليد شعرية أوروبية لاحقة.'}, 'Hadrian': {'hint': 'إمبراطور روماني عُرف بتثبيت حدود الإمبراطورية وبناء سور هادريان في بريطانيا.', 'bio': 'حكم هادريان الإمبراطورية الرومانية من 117 إلى 138م. فضّل في أجزاء من عهده توطيد الحدود على التوسع، وسافر في أنحاء الإمبراطورية واهتم بالعمارة والثقافة اليونانية.', 'achievements': ['أقام سور هادريان لتحديد الحدود الشمالية لبريطانيا الرومانية.', 'أشرف على مشاريع عمرانية واسعة، منها فيلا هادريان ومعبد فينوس وروما.', 'عزز إدارة المقاطعات عبر زياراته الطويلة لأقاليم الإمبراطورية.'], 'key_facts': ['حكم من 117 إلى 138م.', 'ارتبط عهده بثورة بار كوخبا في يهودا.', 'كان عضواً في سلالة الأباطرة الأنطونيين.'], 'wars': ['الحرب اليهودية الثالثة أو ثورة بار كوخبا (132–135م)'], 'historical_significance': 'أعاد هادريان توجيه السياسة الإمبراطورية نحو تثبيت الحدود والإدارة، وبقي سور هادريان أحد أشهر آثار روما.'}, 'Cicero': {'hint': 'خطيب وسياسي وفيلسوف روماني دافع عن الجمهورية واشتهر بخطبه ورسائله.', 'bio': 'كان شيشرون خطيباً ومحامياً وسياسياً وفيلسوفاً من أواخر الجمهورية الرومانية. وصل إلى منصب القنصل وقاد مواجهة سياسية ضد مؤامرة كاتيلينا، ثم اصطدم بالصراعات التي انتهت بسقوط الجمهورية.', 'achievements': ['اشتهر بخطب «الكاتيلينيات» ضد مؤامرة كاتيلينا.', 'كتب أعمالاً فلسفية وخطابية أثرت في دراسة البلاغة والفلسفة اللاتينية.', 'دافع سياسياً وفكرياً عن مؤسسات الجمهورية الرومانية.'], 'key_facts': ['وُلد سنة 106 ق.م. وقُتل سنة 43 ق.م.', 'شغل منصب القنصل سنة 63 ق.م.', 'كان عضواً في مجلس الشيوخ الروماني ومن أبرز خطباء عصره.'], 'wars': [], 'historical_significance': 'حفظت أعمال شيشرون كثيراً من تقاليد البلاغة والفلسفة اللاتينية، وأصبح دفاعه عن الجمهورية مرجعاً سياسياً وفكرياً في عصور لاحقة.'}, 'Marcus Aurelius': {'hint': 'إمبراطور روماني وفيلسوف رواقي كتب «التأملات» أثناء حروب حدودية.', 'bio': 'كان ماركوس أوريليوس إمبراطوراً رومانياً وفيلسوفاً رواقياً حكم من 161 إلى 180م. كتب «التأملات» بوصفها ملاحظات شخصية عن الواجب والانضباط وضبط النفس، بينما واجهت الإمبراطورية حروباً وأوبئة في عهده.', 'achievements': ['ألّف «التأملات» أحد أشهر النصوص الرواقية الباقية.', 'أدار الإمبراطورية خلال حروب الماركومانيين والصراعات الشرقية.', 'واصل تقليد الحكم المرتبط بالسلالة الأنطونية رغم الأزمات العسكرية والوبائية.'], 'key_facts': ['حكم من 161 إلى 180م.', 'شارك في الحكم مع لوشيوس فيروس في جزء من عهده.', 'توفي أثناء حملة عسكرية على الحدود الشمالية.'], 'wars': ['الحرب الرومانية البارثية (161–166م)', 'الحروب الماركومانية (166–180م)'], 'historical_significance': 'أصبح ماركوس أوريليوس نموذجاً للإمبراطور الفيلسوف، وما زالت «التأملات» من أكثر النصوص الرواقية قراءة.'}, 'Scipio Africanus': {'hint': 'القائد الروماني الذي هزم حنبعل في زاما وأنهى التفوق القرطاجي في الحرب البونيقية الثانية.', 'bio': 'كان سكيبيو الإفريقي قائداً عسكرياً وسياسياً رومانياً برز خلال الحرب البونيقية الثانية. نقل الحرب إلى شمال أفريقيا، وانتصر على حنبعل في معركة زاما سنة 202 ق.م.', 'achievements': ['قاد الغزو الروماني لشمال أفريقيا خلال الحرب البونيقية الثانية.', 'هزم حنبعل في معركة زاما سنة 202 ق.م.', 'أسهم انتصاره في فرض شروط أنهت الحرب البونيقية الثانية لصالح روما.'], 'key_facts': ['وُلد نحو 236 ق.م. وتوفي نحو 183 ق.م.', 'كان منتصراً رئيسياً في الحرب البونيقية الثانية.', 'حصل على لقب «الإفريقي» بعد حملته في أفريقيا.'], 'wars': ['الحرب البونيقية الثانية (218–201 ق.م.)', 'معركة زاما (202 ق.م.)'], 'historical_significance': 'غيّر انتصار سكيبيو في زاما ميزان القوى في غرب المتوسط ورسخ صعود روما قوةً كبرى.'}, 'Hannibal Barca': {'hint': 'القائد القرطاجي الذي عبر جبال الألب بالفيلة وهدد روما خلال الحرب البونيقية الثانية.', 'bio': 'كان حنبعل برقا قائداً عسكرياً قرطاجياً قاد الجيوش ضد روما في الحرب البونيقية الثانية. عبر جبال الألب إلى إيطاليا وحقق انتصارات كبرى، أبرزها تريبيا وتراسيميني وكاناي، لكنه لم ينجح في إسقاط روما.', 'achievements': ['عبر جبال الألب بجيش ضم فيلة حربية للوصول إلى إيطاليا.', 'حقق انتصاراً حاسماً على جيش روماني أكبر في معركة كاناي سنة 216 ق.م.', 'طوّر أساليب تطويق ومناورة عسكرية أصبحت موضع دراسة تاريخية واسعة.'], 'key_facts': ['وُلد نحو 247 ق.م. وتوفي نحو 183 أو 181 ق.م.', 'كان ابن القائد القرطاجي حملقار برقا.', 'هُزم أمام سكيبيو الإفريقي في زاما سنة 202 ق.م.'], 'wars': ['الحرب البونيقية الثانية (218–201 ق.م.)', 'معركة كاناي (216 ق.م.)'], 'historical_significance': 'أصبح حنبعل أحد أشهر القادة العسكريين في التاريخ بسبب حملته الإيطالية وانتصاراته على روما رغم تفوقها في الموارد.'}, 'Constantine the Great': {'hint': 'الإمبراطور الذي أعاد توحيد الإمبراطورية الرومانية وارتبط بإضفاء الشرعية على المسيحية.', 'bio': 'كان قسطنطين الأول إمبراطوراً رومانياً وحّد الحكم بعد حروب أهلية، وحكم حتى وفاته سنة 337م. ارتبط اسمه بمرسوم ميلانو سنة 313م وبالمجلس المسكوني الأول في نيقية سنة 325م، كما أسس القسطنطينية عاصمة جديدة.', 'achievements': ['انتصر في معركة جسر ميلفيوس سنة 312م وأصبح الحاكم الأبرز في الغرب.', 'شارك في إقرار سياسة التسامح الديني التي ارتبطت بمرسوم ميلانو.', 'أسس القسطنطينية التي أصبحت عاصمة الإمبراطورية الرومانية الشرقية.'], 'key_facts': ['حكم من 306 إلى 337م.', 'ترأس مجلس نيقية سنة 325م.', 'اعتنق المسيحية وتعمّد قبيل وفاته وفق المصادر القديمة.'], 'wars': ['الحرب الأهلية الرومانية (306–324م)', 'معركة جسر ميلفيوس (312م)'], 'historical_significance': 'غيّر قسطنطين مسار الإمبراطورية الرومانية بتوحيدها وإعادة تشكيل علاقتها بالمسيحية، وكان لتأسيس القسطنطينية أثر طويل في تاريخ أوروبا والشرق.'}, 'Pyrrhus of Epirus': {'hint': 'ملك إبيروس الذي حارب روما وحقق انتصارات باهظة الثمن حتى ارتبط اسمه بعبارة «نصر باهظ الكلفة».', 'bio': 'كان بيروس ملك إبيروس قائداً عسكرياً يونانياً دخل في صراع مع روما في جنوب إيطاليا في القرن الثالث قبل الميلاد. انتصر في هيراكليا وأسقلاوم، لكنه تكبد خسائر كبيرة ثم عاد إلى إبيروس قبل أن يتدخل في صراعات اليونان ومقدونيا.', 'achievements': ['هزم الرومان في معركة هيراكليا سنة 280 ق.م.', 'حقق انتصاراً آخر في أسقلاوم سنة 279 ق.م. رغم الخسائر الكبيرة.', 'قاد حملات لاحقة في مقدونيا واليونان وصقلية.'], 'key_facts': ['حكم إبيروس من نحو 297 إلى 272 ق.م. مع فترات انقطاع.', 'توفي في أرغوس سنة 272 ق.م.', 'أصبح اسمه مصدر التعبير عن «النصر البيروسي».'], 'wars': ['الحرب البيروسية (280–275 ق.م.)', 'معركة هيراكليا (280 ق.م.)', 'معركة أسقلاوم (279 ق.م.)'], 'historical_significance': 'أصبح بيروس مثالاً تاريخياً للقائد الذي يحقق انتصارات تكلفه خسائر تجعل مواصلة الحرب صعبة.'}, 'Attila the Hun': {'hint': 'ملك الهون الذي قاد حملات واسعة ضد الإمبراطورية الرومانية في القرن الخامس.', 'bio': 'كان أتيلا ملكاً للهون وحكم بالاشتراك مع أخيه بليدا ثم منفرداً. قاد حملات في البلقان والغال وإيطاليا وضغط على الإمبراطوريتين الرومانية الشرقية والغربية قبل وفاته سنة 453م.', 'achievements': ['قاد غزوات متكررة ضد الإمبراطورية الرومانية الشرقية.', 'قاد حملة كبرى في بلاد الغال انتهت بمواجهة في سهول كاتالونيا.', 'غزا شمال إيطاليا سنة 452م قبل انسحابه من الحملة.'], 'key_facts': ['حكم منفرداً تقريباً من 445 إلى 453م.', 'توفي سنة 453م بعد زواجه من إيلديكو وفق الرواية التقليدية.', 'كان مركز قوته في السهول الواقعة شمال نهر الدانوب.'], 'wars': ['حملات أتيلا ضد الإمبراطورية الرومانية الشرقية (441–447م)', 'حملة الغال (451م)', 'حملة إيطاليا (452م)'], 'historical_significance': 'مثّل أتيلا إحدى أكبر القوى العسكرية المتنقلة التي ضغطت على العالم الروماني في أواخر العصور القديمة.'}, 'Diogenes': {'hint': 'فيلسوف كلبي اشتهر بنقد الأعراف الاجتماعية والدعوة إلى العيش وفق الطبيعة والبساطة.', 'bio': 'كان ديوجين السينوبي من أشهر فلاسفة المدرسة الكلبية في اليونان القديمة. عُرف بقصصه عن الاستقلال عن الممتلكات والسلطة وبمواجهته للأعراف الاجتماعية، وأصبح رمزاً للفلسفة التي تضع الحرية الشخصية فوق الرفاه المادي.', 'achievements': ['جسّد مبادئ المدرسة الكلبية في حياة شديدة البساطة.', 'استخدم السخرية والحوار لنقد الترف والسلطة والأعراف.', 'أصبح من أشهر الشخصيات الفلسفية في الأدب والحكايات القديمة.'], 'key_facts': ['عاش في القرن الرابع قبل الميلاد.', 'ارتبط بمدينة سينوب ثم أثينا ومدينة كورنثوس.', 'نُسبت إليه حكاية لقائه بالإسكندر الأكبر، مع اختلاف تفاصيلها في المصادر.'], 'wars': [], 'historical_significance': 'أصبح ديوجين رمزاً عالمياً للنقد الجذري للمادية والسلطة الاجتماعية وللاستقلال عن الأعراف.'}, 'Thucydides': {'hint': 'مؤرخ أثيني كتب تاريخ الحرب البيلوبونيسية بمنهج نقدي يعتمد على الشهادة والتحليل.', 'bio': 'كان ثوقيديدس مؤرخاً وقائداً عسكرياً أثينياً في القرن الخامس قبل الميلاد. كتب تاريخ الحرب البيلوبونيسية بين أثينا وإسبرطة، وركز على تفسير الأسباب السياسية والعسكرية بدلاً من الأساطير.', 'achievements': ['كتب «تاريخ الحرب البيلوبونيسية» أحد أهم النصوص التاريخية اليونانية.', 'حلل أسباب الحرب وديناميات القوة والخطاب السياسي.', 'استخدم النقد والمقارنة بين الشهادات لتقليل الروايات غير الموثوقة.'], 'key_facts': ['عاش في القرن الخامس قبل الميلاد.', 'شغل منصب قائد عسكري أثيني قبل نفيه.', 'يتناول عمله الحرب حتى السنوات الأخيرة منها دون إكمال الرواية حتى النهاية.'], 'wars': ['الحرب البيلوبونيسية (431–404 ق.م.)'], 'historical_significance': 'أصبح ثوقيديدس نموذجاً مبكراً للتاريخ التحليلي، ولا تزال طريقته في دراسة القوة والحرب والسياسة مؤثرة في الدراسات التاريخية.'}, 'Euripides': {'hint': 'مسرحي يوناني تناول الأساطير من منظور إنساني ونفسي حاد، ومن أشهر أعماله «ميديا».', 'bio': 'كان يوربيديس أحد أعظم كتاب التراجيديا في أثينا في القرن الخامس قبل الميلاد. أعاد تفسير الأساطير التقليدية وأبرز صراعات الشخصيات ودوافعها، ومن أشهر مسرحياته «ميديا» و«النساء الطرواديات» و«باخوسيات».', 'achievements': ['كتب «ميديا» التي أصبحت من أشهر التراجيديات اليونانية.', 'قدّم شخصيات نسائية ومهمشة بصوت درامي قوي مقارنة بالتقاليد السابقة.', 'طوّر الحوار والشخصية النفسية في التراجيديا الأثينية.'], 'key_facts': ['عاش نحو 480–406 ق.م.', 'كتب أكثر من 90 مسرحية وفق التقاليد القديمة، وبقيت 18 أو 19 كاملة بحسب طريقة العد.', 'قضى أواخر حياته في مقدونيا.'], 'wars': [], 'historical_significance': 'وسّع يوربيديس إمكانات التراجيديا بإعطاء الشخصيات دوافع إنسانية معقدة، وظلت مسرحياته حاضرة في المسرح العالمي.'}, 'Justinian I': {'hint': 'إمبراطور بيزنطي أعاد السيطرة على أجزاء من الغرب وجمع القانون الروماني في «مجموعة جستنيان».', 'bio': 'حكم جستنيان الأول الإمبراطورية الرومانية الشرقية من 527 إلى 565م. سعى لاستعادة أراضٍ غربية عبر حملات عسكرية، وأشرف على تدوين القانون الروماني وبناء آيا صوفيا في القسطنطينية.', 'achievements': ['أصدر مجموعة القوانين التي عُرفت لاحقاً باسم «Corpus Juris Civilis».', 'استعاد شمال أفريقيا وإيطاليا وأجزاء من إسبانيا خلال حملاته.', 'أشرف على بناء آيا صوفيا بعد ثورة نيكا.'], 'key_facts': ['حكم من 527 إلى 565م.', 'كانت زوجته ثيودورا شخصية سياسية مهمة في عهده.', 'توفي سنة 565م وخلفه جستن الثاني.'], 'wars': ['الحرب الوندالية (533–534م)', 'الحرب القوطية (535–554م)'], 'historical_significance': 'أثر جستنيان في القانون الأوروبي عبر تدوين القانون الروماني، وشهد عهده آخر محاولة كبرى لاستعادة أجزاء من الإمبراطورية الرومانية في الغرب.'}, 'Herodotus': {'hint': 'مؤرخ يوناني يُلقب بأبي التاريخ وكتب عن الحروب اليونانية الفارسية وشعوب العالم القديم.', 'bio': 'كان هيرودوت مؤرخاً يونانياً من هاليكارناسوس عاش في القرن الخامس قبل الميلاد. جمع روايات عن الشعوب والأماكن والصراعات وضمّنها في عمله «التواريخ»، مع محاولة التمييز بين ما سمعه وما يراه أكثر احتمالاً.', 'achievements': ['كتب «التواريخ» التي تتناول الحروب اليونانية الفارسية وخلفياتها.', 'قدم أوصافاً جغرافية وثقافية لمصر وبلاد فارس واليونان ومناطق أخرى.', 'جمع الرواية التاريخية مع ملاحظات عن العادات والأساطير والمجتمعات.'], 'key_facts': ['عاش نحو 484–425 ق.م.', 'وُلد في هاليكارناسوس في آسيا الصغرى.', 'يُعد من أوائل المؤرخين الذين وصل عملهم إلينا بصورة واسعة.'], 'wars': ['الحروب اليونانية الفارسية (499–449 ق.م.)'], 'historical_significance': 'أسس هيرودوت تقليداً تاريخياً يجمع بين السرد والتحقيق في أسباب الأحداث، ولهذا ارتبط اسمه ببدايات كتابة التاريخ.'}, 'Sophocles': {'hint': 'مسرحي أثيني كتب «أوديب ملكاً» وكان من أعمدة التراجيديا اليونانية.', 'bio': 'كان سوفوكليس أحد أبرز كتاب التراجيديا في أثينا في القرن الخامس قبل الميلاد. كتب أكثر من مئة مسرحية وفق المصادر القديمة، وبقيت سبع مسرحيات كاملة، منها «أوديب ملكاً» و«أنتيغونِه».', 'achievements': ['كتب «أوديب ملكاً» التي أصبحت نموذجاً للبناء التراجيدي.', 'طوّر تقنيات المسرح الأثيني وزاد عدد الممثلين في العرض وفق التقاليد القديمة.', 'فاز بمسابقات درامية كثيرة في مهرجانات أثينا.'], 'key_facts': ['عاش نحو 496–406 ق.م.', 'كان معاصراً ليوربيديس وإسخيلوس.', 'خدم أثينا في أدوار سياسية وعسكرية إلى جانب نشاطه المسرحي.'], 'wars': ['الحرب الساموسية (441–439 ق.م.)'], 'historical_significance': 'أثرت أعمال سوفوكليس، خصوصاً «أوديب ملكاً»، في نظرية التراجيديا وفي المسرح والأدب العالميين.'}, 'Leonidas I': {'hint': 'ملك إسبرطي قاد المدافعين اليونانيين في معركة ترموبيل أثناء الغزو الفارسي.', 'bio': 'كان ليونيداس الأول ملكاً إسبرطياً من أسرة الأجياد. قاد قوة يونانية صغيرة في ممر ترموبيل سنة 480 ق.م. وشارك في مقاومة الجيش الفارسي قبل مقتله مع معظم قوته.', 'achievements': ['قاد المدافعين اليونانيين في ترموبيل سنة 480 ق.م.', 'أصبح موته رمزاً للتضحية العسكرية في الذاكرة اليونانية.', 'أسهمت مقاومة ترموبيل في إبطاء التقدم الفارسي قبل المعارك اللاحقة.'], 'key_facts': ['حكم إسبرطة حتى مقتله سنة 480 ق.م.', 'كان أخاً غير شقيق للملك كليومينس الأول.', 'قُتل في معركة ترموبيل أثناء الغزو الفارسي الثاني لليونان.'], 'wars': ['الغزو الفارسي الثاني لليونان (480–479 ق.م.)', 'معركة ترموبيل (480 ق.م.)'], 'historical_significance': 'أصبح ليونيداس رمزاً للشجاعة العسكرية بسبب قيادة المقاومة في ترموبيل والقتال حتى الموت.'}, 'Pythagoras': {'hint': 'فيلسوف ورياضي يوناني ارتبط اسمه بالمجتمع الفيثاغوري وبالنظرية الشهيرة في المثلثات.', 'bio': 'كان فيثاغورس مفكراً يونانياً عاش في القرن السادس قبل الميلاد وأسّس جماعة دينية وفلسفية في جنوب إيطاليا. ارتبطت جماعته بدراسة الأعداد والموسيقى والهندسة، لكن كثيراً من التفاصيل المنسوبة إليه يصعب فصلها عن أعمال أتباعه.', 'achievements': ['أسس المدرسة الفيثاغورية في كروتون أو حولها.', 'ارتبط تقليدياً بدراسة العلاقات العددية في الموسيقى والهندسة.', 'أثر في الفلسفة اليونانية اللاحقة عبر جماعته وأفكارها عن العدد والنظام.'], 'key_facts': ['عاش تقريباً بين 570 و495 ق.م.', 'نشط في جنوب إيطاليا بعد مغادرته ساموس.', 'نظرية فيثاغورس تحمل اسمه، لكن نسبة اكتشافها إليه شخصياً ليست مؤكدة تاريخياً.'], 'wars': [], 'historical_significance': 'أصبحت المدرسة الفيثاغورية جسراً بين البحث الرياضي والتأمل الفلسفي والديني في الفكر اليوناني القديم.'}, 'Edward III': {'hint': 'ملك إنجلترا الذي حكم لأكثر من نصف قرن وقاد إنجلترا في المراحل الأولى من حرب المئة عام.', 'bio': 'حكم إدوارد الثالث إنجلترا من 1327 إلى 1377م. طالب بالعرش الفرنسي، وحقق جيشه انتصارات مهمة مثل كريسي وبواتييه، بينما شهد عهده تطور المؤسسات البرلمانية وتأسيس وسام الرباط.', 'achievements': ['قاد إنجلترا إلى انتصارات كبرى في حرب المئة عام.', 'أسس تقليد وسام الرباط في منتصف القرن الرابع عشر.', 'عزز مكانة البرلمان والفرسان في الحكم الإنجليزي خلال عهده.'], 'key_facts': ['حكم من 1327 إلى 1377م.', 'كان ابنه الأكبر الأمير الأسود قائداً عسكرياً بارزاً.', 'توفي سنة 1377 وخلفه حفيده ريتشارد الثاني.'], 'wars': ['حرب المئة عام (1337–1453م)', 'معركة كريسي (1346م)', 'معركة بواتييه (1356م)'], 'historical_significance': 'جعل إدوارد الثالث إنجلترا قوة عسكرية بارزة في أوروبا الغربية ورسّخ المطالبة الإنجليزية بالعرش الفرنسي.'}, 'Jan van Eyck': {'hint': 'رسام فلمنكي من القرن الخامس عشر ارتبط بالتفاصيل الدقيقة وتقنيات الرسم الزيتي.', 'bio': 'كان يان فان إيك من أبرز رسامي هولندا الفلمنكية في القرن الخامس عشر. عمل في بلاط دوق بورغندي واشتهر بأعمال مثل «بورتريه أرنولفيني» و«مذبح غنت» بالتعاون مع أخيه هوبرت وفق تقليد العمل.', 'achievements': ['أنجز لوحات دينية وبورتريهات ذات تفاصيل دقيقة بصورة استثنائية.', 'ارتبط بمذبح غنت، أحد أهم الأعمال الفنية الفلمنكية المبكرة.', 'طور استخدام الطبقات الزجاجية والمواد الزيتية ضمن تقاليد الرسم الفلمنكي.'], 'key_facts': ['عاش نحو 1390–1441م.', 'عمل في بلاط فيليب الطيب دوق بورغندي.', 'لوحة «بورتريه أرنولفيني» مؤرخة سنة 1434.'], 'wars': [], 'historical_significance': 'كان فان إيك من أهم الفنانين في تطور الرسم الفلمنكي، وأسهمت تقنياته في رفع مكانة الرسم الزيتي في أوروبا.'}, 'Joan of Arc': {'hint': 'بطلة فرنسية قادت قوات شارل السابع في حصار أورليان خلال حرب المئة عام.', 'bio': 'كانت جان دارك فلاحـة فرنسية قالت إنها تلقت رؤى دينية تدعوها لمساندة شارل السابع. شاركت في رفع حصار أورليان سنة 1429 وساعدت في دفع مسار تتويج شارل، ثم أُسرت وأُعدمت سنة 1431 قبل أن يُعاد النظر في محاكمتها.', 'achievements': ['شاركت في رفع حصار أورليان سنة 1429.', 'رافقت شارل السابع إلى ريمس حيث تُوّج ملكاً.', 'أصبحت رمزاً للمقاومة الفرنسية خلال حرب المئة عام.'], 'key_facts': ['وُلدت نحو 1412م وأُعدمت سنة 1431م.', 'أُسرت في 1430 وسُلّمت إلى الإنجليز وحلفائهم.', 'أُبطلت إدانتها في مراجعة كنسية سنة 1456، ثم أعلنت قديسة في 1920.'], 'wars': ['حرب المئة عام (1337–1453م)', 'حصار أورليان (1428–1429م)'], 'historical_significance': 'تحولت جان دارك من شخصية عسكرية قصيرة العمر إلى رمز قومي وديني فرنسي ذي تأثير عالمي.'}, 'Mehmed II': {'hint': 'السلطان العثماني الذي فتح القسطنطينية سنة 1453 وأنهى الإمبراطورية البيزنطية.', 'bio': 'كان محمد الثاني سلطاناً عثمانياً حكم على فترتين، واشتهر بفتح القسطنطينية سنة 1453 وهو في الحادية والعشرين تقريباً. وسّع الدولة في البلقان والأناضول وحوّل القسطنطينية إلى مركز سياسي عثماني.', 'achievements': ['فتح القسطنطينية في 29 مايو 1453م.', 'أنهى الإمبراطورية البيزنطية كقوة سياسية مستقلة.', 'وسع الدولة العثمانية في الأناضول والبلقان وأعاد تنظيم العاصمة.'], 'key_facts': ['وُلد سنة 1432 وتوفي سنة 1481م.', 'حكم أولاً 1444–1446 ثم 1451–1481م.', 'لُقّب بـ«الفاتح» بعد فتح القسطنطينية.'], 'wars': ['فتح القسطنطينية (1453م)', 'الحروب العثمانية في البلقان والأناضول خلال القرن الخامس عشر'], 'historical_significance': 'غيّر فتح القسطنطينية ميزان القوى بين العثمانيين وأوروبا، وجعل المدينة عاصمة إمبراطورية استمرت قروناً.'}, 'Isabella I': {'hint': 'ملكة قشتالة التي حكمت مع فرناندو الثاني وارتبط عهدها بتوحيد إسبانيا ورحلة كولومبوس.', 'bio': 'كانت إيزابيلا الأولى ملكة قشتالة وحكمت مع زوجها فرناندو الثاني ملك أراغون. دعما حرب غرناطة، وأنهيا الحكم الإسلامي في الأندلس سنة 1492، كما موّلا رحلة كريستوفر كولومبوس عبر الأطلسي.', 'achievements': ['دعمت مع فرناندو الثاني حرب غرناطة وانتهت بسقوطها سنة 1492.', 'موّلت رحلة كريستوفر كولومبوس الأولى عبر الأطلسي.', 'عززت السلطة الملكية وأعادت تنظيم مؤسسات الحكم في قشتالة.'], 'key_facts': ['وُلدت سنة 1451 وتوفيت سنة 1504م.', 'تزوجت فرناندو الثاني سنة 1469.', 'حكمت قشتالة من 1474 إلى 1504م.'], 'wars': ['حرب خلافة قشتالة (1475–1479م)', 'حرب غرناطة (1482–1492م)'], 'historical_significance': 'كان عهد إيزابيلا وفرناندو نقطة تحول في بناء الملكية الإسبانية وفي توسع إسبانيا الأطلسي بعد 1492.'}, 'Christopher Columbus': {'hint': 'ملاح جنوي قاد رحلة إسبانية عبر الأطلسي سنة 1492 ووصل إلى جزر الكاريبي.', 'bio': 'قاد كريستوفر كولومبوس رحلات بحرية بتمويل من التاجين القشتالي والأراغوني بحثاً عن طريق غربي إلى آسيا. وصل في أكتوبر 1492 إلى جزر في الكاريبي، ثم قاد رحلات أخرى إلى العالم الجديد.', 'achievements': ['قاد الرحلة الأطلسية الأولى التي بدأت من إسبانيا سنة 1492.', 'أسس نقاط اتصال أوروبية دائمة مع جزر الكاريبي في رحلاته اللاحقة.', 'سجّل ملاحظات جغرافية وبحرية أثرت في الملاحة الأوروبية اللاحقة.'], 'key_facts': ['وُلد نحو 1451 وتوفي سنة 1506م.', 'وصل إلى جزيرة من جزر الباهاما في 12 أكتوبر 1492.', 'أجرى أربع رحلات عبر الأطلسي تحت رعاية التاج الإسباني.'], 'wars': [], 'historical_significance': 'أصبحت رحلات كولومبوس نقطة تحول في تاريخ الأطلسي، وأدت إلى اتصال دائم بين أوروبا والأمريكيتين وما تبعه من تحولات سكانية واقتصادية.'}, 'Ferdinand II': {'hint': 'ملك أراغون الذي حكم مع إيزابيلا الأولى وشارك في توحيد الملكيات الإسبانية وسقوط غرناطة.', 'bio': 'كان فرناندو الثاني ملك أراغون وزوج إيزابيلا الأولى ملكة قشتالة. حكم معها خلال توسع السلطة الملكية، وحرب غرناطة، وبدايات التوسع الإسباني عبر الأطلسي.', 'achievements': ['شارك في حرب غرناطة التي انتهت بسقوطها سنة 1492.', 'وحّد مع إيزابيلا الإدارة السياسية لملكيتي قشتالة وأراغون مع بقاء مؤسساتهما منفصلة.', 'دعم رحلات كولومبوس والتوسع الإسباني خارج شبه الجزيرة الإيبيرية.'], 'key_facts': ['وُلد سنة 1452 وتوفي سنة 1516م.', 'تزوج إيزابيلا الأولى سنة 1469.', 'حكم أراغون من 1479 إلى 1516م.'], 'wars': ['حرب خلافة قشتالة (1475–1479م)', 'حرب غرناطة (1482–1492م)'], 'historical_significance': 'أسهم فرناندو وإيزابيلا في بناء الملكية الإسبانية الصاعدة وربطا سقوط غرناطة ببداية مرحلة التوسع الأطلسي.'}, 'Amerigo Vespucci': {'hint': 'ملاح فلورنسي ارتبطت رحلاته بالاستنتاج بأن الأراضي المكتشفة غرب الأطلسي ليست آسيا بل قارة جديدة.', 'bio': 'كان أمريغو فسبوتشي ملاحاً وتاجراً فلورنسي الأصل شارك في رحلات إلى سواحل العالم الجديد في أواخر القرن الخامس عشر وبدايات السادس عشر. أسهمت رسائله في نشر تصور جغرافي جديد للأراضي الواقعة غرب الأطلسي.', 'achievements': ['شارك في رحلات استكشافية إلى سواحل أمريكا الجنوبية.', 'ساعدت كتاباته المنشورة في ترسيخ فكرة أن العالم الجديد كتلة قارية منفصلة عن آسيا.', 'ارتبط اسمه بتسمية القارتين الأمريكيتين في خرائط أوروبا.'], 'key_facts': ['وُلد سنة 1454 وتوفي سنة 1512م.', 'كان من فلورنسا وعمل في التجارة والملاحة.', 'توجد خلافات تاريخية حول تفاصيل بعض الرحلات المنسوبة إليه.'], 'wars': [], 'historical_significance': 'أسهم فسبوتشي في التحول الجغرافي الأوروبي من تصور الأراضي الجديدة كجزء من آسيا إلى فهمها كقارات مستقلة، ومنها جاء اسم أمريكا.'}, 'Vasco da Gama': {'hint': 'ملاح برتغالي قاد أول رحلة بحرية مباشرة من أوروبا إلى الهند حول رأس الرجاء الصالح.', 'bio': 'كان فاسكو دا غاما ملاحاً برتغالياً قاد الرحلة التي وصلت إلى كاليكوت في الهند سنة 1498 بعد الدوران حول رأس الرجاء الصالح. مثّل وصوله نجاحاً برتغالياً في فتح طريق بحري مباشر إلى تجارة المحيط الهندي.', 'achievements': ['وصل بحراً من البرتغال إلى الهند سنة 1498.', 'فتح الطريق البحري البرتغالي حول رأس الرجاء الصالح إلى المحيط الهندي.', 'شارك في ترسيخ الوجود البرتغالي التجاري والعسكري في المحيط الهندي.'], 'key_facts': ['وُلد نحو 1460 وتوفي سنة 1524م.', 'وصل إلى كاليكوت في مايو 1498.', 'قاد لاحقاً حملات برتغالية إلى الهند وشغل منصب نائب الملك هناك.'], 'wars': ['الصراع البرتغالي في المحيط الهندي في بدايات القرن السادس عشر'], 'historical_significance': 'غيّر طريق فاسكو دا غاما البحري حركة التجارة بين أوروبا وآسيا ومهّد لهيمنة برتغالية على أجزاء من طرق المحيط الهندي.'}, 'Selim I': {'hint': 'سلطان عثماني وسّع الدولة جنوباً وشرقاً وضم الشام ومصر والحجاز إلى النفوذ العثماني.', 'bio': 'حكم سليم الأول الدولة العثمانية من 1512 إلى 1520م. هزم الصفويين في جالديران ثم انتصر على المماليك في مرج دابق والريدانية، فامتد الحكم العثماني إلى بلاد الشام ومصر والحجاز.', 'achievements': ['انتصر على الصفويين في معركة جالديران سنة 1514.', 'هزم المماليك في مرج دابق سنة 1516 والريدانية سنة 1517.', 'وسّع الدولة العثمانية لتشمل مصر وبلاد الشام والحجاز.'], 'key_facts': ['وُلد سنة 1470 وتوفي سنة 1520م.', 'حكم ثماني سنوات تقريباً.', 'كان ابنه سليمان القانوني خليفته.'], 'wars': ['الحرب العثمانية الصفوية (1514م)', 'الحرب العثمانية المملوكية (1516–1517م)'], 'historical_significance': 'حوّل سليم الأول مركز الثقل العثماني نحو الشرق والجنوب ورسخ سيطرة الدولة على مراكز مهمة في العالم العربي.'}, 'Nicolaus Copernicus': {'hint': 'فلكي بولندي اقترح نموذجاً يجعل الشمس مركز النظام بدلاً من الأرض.', 'bio': 'كان نيقولا كوبرنيكوس فلكياً ورياضياً ورجل دين من عصر النهضة. في كتابه «دوران الأجرام السماوية» قدّم نموذجاً مركزه الشمس، متحدياً النموذج الأرضي السائد في علم الفلك الأوروبي.', 'achievements': ['صاغ نموذجاً مركزه الشمس لحركة الكواكب.', 'نشر «دوران الأجرام السماوية» سنة 1543.', 'أسهم نموذجه في إطلاق التحول الذي صار يعرف بالثورة الكوبرنيكية.'], 'key_facts': ['وُلد سنة 1473 وتوفي سنة 1543م.', 'عمل في فرومبورك وكان مرتبطاً بالكنيسة.', 'نُشر كتابه الفلكي الرئيسي في سنة وفاته.'], 'wars': [], 'historical_significance': 'كان نموذج كوبرنيكوس نقطة انطلاق مركزية للثورة العلمية التي أعادت صياغة فهم الإنسان لبنية الكون.'}, 'Michelangelo': {'hint': 'فنان عصر النهضة الذي رسم سقف كنيسة سيستينا ونحت «داود» و«بييتا».', 'bio': 'كان ميكيلانجلو نحاتاً ورساماً ومعمارياً وشاعراً إيطالياً من عصر النهضة. عمل في فلورنسا وروما وأنجز أعمالاً أصبحت من أشهر رموز الفن الأوروبي، ومنها «داود» وسقف كنيسة سيستينا.', 'achievements': ['نحت تمثال «داود» في فلورنسا.', 'رسم مشاهد سقف كنيسة سيستينا في روما.', 'أنجز تمثال «بييتا» وصمم أجزاء مهمة من عمارة كنيسة القديس بطرس.'], 'key_facts': ['وُلد سنة 1475 وتوفي سنة 1564م.', 'عمل تحت رعاية البابوات ومراكز الحكم في إيطاليا.', 'كان من أبرز فناني النهضة العليا.'], 'wars': [], 'historical_significance': 'جسّد ميكيلانجلو إمكانات فن عصر النهضة في النحت والرسم والعمارة، وأصبح تأثيره أساسياً في تاريخ الفن الغربي.'}, 'Ferdinand Magellan': {'hint': 'مستكشف برتغالي قاد الحملة التي بدأت أول دورة موثقة حول الأرض، لكنه قُتل قبل اكتمالها.', 'bio': 'قاد فرديناند ماجلان حملة إسبانية انطلقت سنة 1519 بحثاً عن طريق غربي إلى جزر التوابل. عبر المضيق الذي يحمل اسمه ووصل إلى المحيط الهادئ، وقُتل في الفلبين سنة 1521، ثم أكملت الحملة الرحلة حول العالم بقيادة آخرين.', 'achievements': ['قاد الحملة التي عبرت من الأطلسي إلى الهادئ عبر مضيق ماجلان.', 'وصلت حملته إلى جزر الفلبين سنة 1521.', 'أكملت سفينة فيكتوريا التابعة للحملة أول دورة حول الأرض ضمن رحلة واحدة.'], 'key_facts': ['وُلد نحو 1480 وتوفي سنة 1521م.', 'كان برتغالياً يعمل لصالح التاج الإسباني.', 'لم يكن ماجلان نفسه على متن السفينة التي أكملت الدورة.'], 'wars': ['معركة ماكتان (1521م)'], 'historical_significance': 'أثبتت الحملة التي قادها ماجلان عملياً حجم المحيط الهادئ والترابط البحري بين المحيطات، وغيرت تصور الأوروبيين لجغرافية العالم.'}, 'Raphael': {'hint': 'رسام عصر النهضة الإيطالي صاحب «مدرسة أثينا» وأحد رموز النهضة العليا.', 'bio': 'كان رافائيل رساماً ومعمارياً إيطالياً من عصر النهضة العليا. عمل في فلورنسا وروما، ورسم غرف الفاتيكان ومنها «مدرسة أثينا»، وأصبح أسلوبه نموذجاً للانسجام والتوازن في الرسم الأوروبي.', 'achievements': ['رسم «مدرسة أثينا» في غرف الفاتيكان.', 'أنجز لوحات عديدة للعذراء والطفل ولصور الشخصيات والنبلاء.', 'عمل في العمارة في روما وأسهم في مشاريع الفاتيكان.'], 'key_facts': ['وُلد سنة 1483 وتوفي سنة 1520م.', 'عمل في بلاط البابا يوليوس الثاني ثم ليو العاشر.', 'توفي في روما في سن السابعة والثلاثين.'], 'wars': [], 'historical_significance': 'أصبح رافائيل أحد النماذج الكبرى للنهضة العليا، وأثر أسلوبه المتوازن في أجيال من الرسامين والأكاديميات الفنية.'}, 'Titian': {'hint': 'رسام البندقية الكبير الذي اشتهر بالصور الدينية والأسطورية والبورتريهات واستخدام اللون.', 'bio': 'كان تيتيان فيتشيللي من أعظم رسامي البندقية في القرن السادس عشر. عمل لصالح حكام وأمراء أوروبيين، واشتهر باللون والضوء وبأعمال دينية وأساطير وبورتريهات ذات تأثير طويل.', 'achievements': ['رسم أعمالاً أسطورية مثل «فينوس أوربينو» و«باخوس وأريادني».', 'أنجز بورتريهات لأمراء وملوك وشخصيات سياسية بارزة.', 'طوّر تقاليد الرسم اللوني في مدرسة البندقية.'], 'key_facts': ['وُلد نحو 1488 أو 1490 وتوفي سنة 1576م.', 'عمل في البندقية وروما ومراكز أوروبية أخرى.', 'كان من أكثر الفنانين تأثيراً في الرسم الأوروبي في القرن السادس عشر.'], 'wars': [], 'historical_significance': 'كان تيتيان محورياً في ترسيخ أولوية اللون واللمسة الزيتية في الفن الأوروبي، وأثر في روبنز وفلاسفة الرسم اللاحقين.'}, 'Henry VIII': {'hint': 'ملك إنجلترا الذي انفصلت في عهده كنيسة إنجلترا عن سلطة البابا في روما.', 'bio': 'حكم هنري الثامن إنجلترا من 1509 إلى 1547م. ارتبط عهده بالإصلاح الإنجليزي وبإنشاء كنيسة إنجلترا المستقلة عن البابوية، كما اشتهر بزواجه من ست زوجات وبالصراعات الدينية والسياسية.', 'achievements': ['أقر قوانين جعلت الملك والرئاسة الملكية محور الكنيسة الإنجليزية.', 'أشرف على حل الأديرة ومصادرة ممتلكات كثيرة تابعة لها.', 'عزز البحرية الإنجليزية والقدرة المالية والعسكرية للتاج.'], 'key_facts': ['وُلد سنة 1491 وتوفي سنة 1547م.', 'تزوج ست مرات.', 'خلفه ابنه إدوارد السادس ثم ابنتاه ماري وإليزابيث في مراحل لاحقة.'], 'wars': ['الحرب الإيطالية (1521–1526م)', 'الحرب الإنجليزية الفرنسية (1543–1546م)'], 'historical_significance': 'غيّر عهد هنري الثامن العلاقة بين الدولة والكنيسة في إنجلترا ومهّد لمسار ديني وسياسي مختلف عن أوروبا الكاثوليكية.'}, 'Suleiman': {'hint': 'سليمان القانوني، السلطان العثماني الذي بلغت الدولة في عهده ذروة واسعة من النفوذ العسكري والقانوني.', 'bio': 'حكم سليمان الأول الدولة العثمانية من 1520 إلى 1566م. قاد حملات في أوروبا والشرق الأوسط والبحر المتوسط، وارتبط اسمه بتنظيم القوانين وبالازدهار العمراني والثقافي في إسطنبول.', 'achievements': ['فتح بلغراد سنة 1521 وحاصر فيينا سنة 1529.', 'ضم بغداد والعراق في سياق الحرب مع الصفويين.', 'أصدر تنظيماً واسعاً للقوانين العثمانية واشتهر بلقب القانوني.'], 'key_facts': ['وُلد سنة 1494 وتوفي سنة 1566م.', 'حكم قرابة 46 عاماً.', 'كان المعماري سنان من أبرز فناني عهده.'], 'wars': ['الحرب العثمانية المجرية (1521–1526م)', 'الحرب العثمانية الصفوية (1532–1555م)', 'الحصار العثماني لفيينا (1529م)'], 'historical_significance': 'يمثل عهد سليمان إحدى قمم القوة العثمانية في السياسة والقانون والفنون، ورسخ صورة الإمبراطورية كقوة أوروبية وشرق أوسطية كبرى.'}, 'Charles V': {'hint': 'إمبراطور روماني مقدس وملك إسباني حكم إمبراطورية واسعة وواجه فرنسا والعثمانيين والإصلاح البروتستانتي.', 'bio': 'كان شارل الخامس إمبراطور الإمبراطورية الرومانية المقدسة وملك إسبانيا في القرن السادس عشر. حكم أراضي واسعة في أوروبا والأمريكتين، وخاض حروباً مع فرنسا والعثمانيين، كما واجه انقسام المسيحية خلال الإصلاح البروتستانتي.', 'achievements': ['حكم اتحاداً واسعاً من الأراضي الإسبانية والهابسبورغية.', 'حارب فرنسا في سلسلة من الحروب على الهيمنة الأوروبية.', 'واجه توسع العثمانيين والإصلاح البروتستانتي خلال عهده.'], 'key_facts': ['وُلد سنة 1500 وتوفي سنة 1558م.', 'انتُخب إمبراطوراً رومياً مقدساً سنة 1519.', 'تنازل عن العرش سنة 1556 وقسم أملاكه بين فرعي آل هابسبورغ.'], 'wars': ['الحروب الإيطالية (1494–1559م)', 'الحرب العثمانية الهابسبورغية في القرن السادس عشر'], 'historical_significance': 'يجسد شارل الخامس ذروة القوة الهابسبورغية في أوروبا في عصر شهد صعود الدول المركزية والإصلاح الديني والتوسع العالمي.'}, 'Elizabeth I': {'hint': 'ملكة إنجلترا التي شهد عهدها هزيمة الأرمادا الإسبانية وازدهار الأدب الإنجليزي في العصر الإليزابيثي.', 'bio': 'حكمت إليزابيث الأولى إنجلترا من 1558 إلى 1603م. حافظت على تسوية دينية بروتستانتية، وواجهت إسبانيا، وشهد عهدها ازدهار المسرح والشعر الإنجليزي، بما في ذلك أعمال شكسبير.', 'achievements': ['هزمت إنجلترا الأرمادا الإسبانية سنة 1588.', 'دعمت استقرار التسوية الدينية الإنجليزية.', 'شهد عهدها ازدهار المسرح والأدب والاستكشاف البحري الإنجليزي.'], 'key_facts': ['وُلدت سنة 1533 وتوفيت سنة 1603م.', 'كانت آخر ملوك أسرة تيودور.', 'لم تتزوج ولذلك عُرفت بلقب «الملكة العذراء».'], 'wars': ['الحرب الإنجليزية الإسبانية (1585–1604م)', 'هزيمة الأرمادا الإسبانية (1588م)'], 'historical_significance': 'أصبحت إليزابيث رمزاً للدولة الإنجليزية في عصر توسع بحري وثقافي، وشكّل عهدها مرحلة مهمة في تاريخ إنجلترا الحديث المبكر.'}, 'Oda Nobunaga': {'hint': 'أحد القادة الذين بدأوا توحيد اليابان في القرن السادس عشر باستخدام الأسلحة النارية والإصلاح العسكري.', 'bio': 'كان أودا نوبوناغا قائداً إقطاعياً يابانياً في فترة الدول المتحاربة. وسّع نفوذه بسرعة، واستفاد من الأسلحة النارية في تنظيم قواته، لكنه اغتيل في حادثة هونّو-جي سنة 1582 قبل إكمال توحيد اليابان.', 'achievements': ['هزم قوات تاكيدا باستخدام تشكيلات مشاة مسلحة بالبنادق في ناغاشينو سنة 1575.', 'سيطر على كيوتو وأضعف سلطة منافسين عسكريين ودينيين.', 'بدأ عملية توحيد اليابان التي أكملها لاحقاً تويوتومي هيديوشي وتوكوغاوا إياسو.'], 'key_facts': ['وُلد سنة 1534 وتوفي سنة 1582م.', 'اغتيل في حادثة هونّو-جي على يد أكيتشي ميتسوهيده.', 'كان من أبرز شخصيات فترة سينغوكو.'], 'wars': ['حرب أونينجيوكو وحروب توحيد اليابان في فترة سينغوكو', 'معركة ناغاشينو (1575م)'], 'historical_significance': 'كان نوبوناغا من أهم مهندسي توحيد اليابان، وأسهم في تحويل الحرب الإقطاعية باستخدام التنظيم المركزي والأسلحة النارية.'}, 'Toyotomi Hideyoshi': {'hint': 'قائد ياباني أكمل معظم توحيد اليابان بعد نوبوناغا ثم حاول غزو كوريا.', 'bio': 'كان تويوتومي هيديوشي قائداً عسكرياً وسياسياً صعد من رتبة متواضعة إلى مركز حاكم اليابان الفعلي. أكمل توحيد معظم البلاد، ثم شن غزوتين كبيرتين لكوريا قبل وفاته سنة 1598.', 'achievements': ['أكمل توحيد اليابان بعد وفاة أودا نوبوناغا.', 'نفذ إصلاحات في تسجيل الأراضي والطبقات الاجتماعية وحيازة السلاح.', 'قاد الغزو الياباني لكوريا ابتداءً من 1592.'], 'key_facts': ['وُلد سنة 1537 وتوفي سنة 1598م.', 'لم يصبح شوغوناً رسمياً لكنه حكم البلاد فعلياً.', 'خلفه مجلس من خمسة أوصياء قبل صعود توكوغاوا إياسو.'], 'wars': ['حملات توحيد اليابان (القرن السادس عشر)', 'الحرب اليابانية على كوريا (1592–1598م)'], 'historical_significance': 'أكمل هيديوشي توحيد اليابان السياسي قبل عصر توكوغاوا، وأعادت سياساته تشكيل المجتمع والسلطة المركزية.'}, 'El Greco': {'hint': 'فنان كريتي إسباني اشتهر بالأجسام الممدودة والضوء الدرامي في أعماله الدينية.', 'bio': 'كان إل غريكو، واسمه دومينيكوس ثيوتوكوبولوس، فناناً من جزيرة كريت استقر في إسبانيا، خصوصاً في طليطلة. جمع بين تقاليد الفن البيزنطي والإيطالي والأسلوب الشخصي القوي، واشتهر بأعمال دينية وبورتريهات.', 'achievements': ['رسم «دفن كونت أورغاز» في طليطلة.', 'أنجز سلسلة من اللوحات الدينية ذات الأشكال الممدودة والإضاءة الدرامية.', 'طور أسلوباً مميزاً أثر لاحقاً في بعض اتجاهات الفن الحديث.'], 'key_facts': ['وُلد سنة 1541 وتوفي سنة 1614م.', 'تدرب في كريت ثم عمل في البندقية وروما قبل إسبانيا.', 'ارتبطت معظم مسيرته الإسبانية بمدينة طليطلة.'], 'wars': [], 'historical_significance': 'أصبح إل غريكو جسراً فنياً بين تقاليد كريت وإيطاليا وإسبانيا، واكتُشف تأثيره من جديد في تاريخ الفن الحديث.'}, 'Akbar': {'hint': 'إمبراطور مغولي في الهند وسّع الإمبراطورية وعُرف بسياسات إدارية وتسامح ديني نسبي.', 'bio': 'كان أكبر أعظم حكام الإمبراطورية المغولية في الهند، وحكم من 1556 إلى 1605م. وسّع الدولة عسكرياً، ونظم الإدارة والضرائب، واتبع سياسات استيعاب تجاه جماعات دينية متعددة.', 'achievements': ['وسّع الإمبراطورية المغولية في شمال ووسط الهند.', 'نظم نظام الإيرادات والإدارة الإقليمية عبر إصلاحات مرتبطة بتودار مال.', 'ألغى الجزية عن غير المسلمين لفترة وسعى إلى حوار ديني في بلاطه.'], 'key_facts': ['وُلد سنة 1542 وتوفي سنة 1605م.', 'خلف والده همايون في سن صغيرة.', 'أسس مدينة فاتحبور سيكري كمركز إمبراطوري لفترة.'], 'wars': ['الحروب المغولية في شمال ووسط الهند (القرن السادس عشر)', 'الحرب مع مملكة ميوار'], 'historical_significance': 'رسخ أكبر دولة مغولية قوية في الهند، وأسهمت إدارته وسياساته الدينية في تشكيل نموذج الحكم المغولي لقرون لاحقة.'}}

def rebuild_js(data: dict[str, Any]) -> None:
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    JS_PATH.parent.mkdir(parents=True, exist_ok=True)
    JS_PATH.write_text(
        "window.PERSON_I18N = " + payload + ";\n",
        encoding="utf-8",
    )

def load_js_semantics() -> dict[str, Any]:
    text = JS_PATH.read_text(encoding="utf-8-sig")
    prefix = "window.PERSON_I18N = "
    if not text.startswith(prefix):
        raise RuntimeError("Could not parse person_i18n.js")
    payload = text[len(prefix):].strip()
    if payload.endswith(";"):
        payload = payload[:-1].rstrip()
    if not payload:
        raise RuntimeError("Empty PERSON_I18N payload")
    try:
        parsed = json.loads(payload)
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            f"Could not parse person_i18n.js: {exc}"
        ) from exc
    if not isinstance(parsed, dict):
        raise RuntimeError("PERSON_I18N payload is not an object")
    return parsed

def main() -> int:
    parser = argparse.ArgumentParser(
        description="Apply Map of Fame Arabic Batch 07"
    )
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()

    if not JSON_PATH.exists():
        raise FileNotFoundError(JSON_PATH)
    if not JS_PATH.exists():
        raise FileNotFoundError(JS_PATH)

    data = json.loads(JSON_PATH.read_text(encoding="utf-8-sig"))
    people = data.get("people")
    if not isinstance(people, dict):
        raise RuntimeError("Invalid people object")

    if data.get("languages") != EXPECTED_LANGUAGES:
        raise RuntimeError(
            "Unexpected language list; refusing to change it: "
            + repr(data.get("languages"))
        )

    missing = [name for name in BATCH if name not in people]
    if missing:
        raise RuntimeError("Missing person keys: " + ", ".join(missing))

    if not args.apply:
        print(f"DRY RUN — Arabic Batch 07: {len(BATCH)} people")
        print("No files changed. Run with --apply to apply it.")
        return 0

    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    json_backup = BACKUP_DIR / f"person_i18n_ar_batch07_{stamp}.json"
    js_backup = BACKUP_DIR / f"person_i18n_ar_batch07_{stamp}.js"

    shutil.copy2(JSON_PATH, json_backup)
    shutil.copy2(JS_PATH, js_backup)

    changed_fields = 0
    for name, patch in BATCH.items():
        languages = people[name].setdefault("languages", {})
        ar = languages.get("ar")
        if not isinstance(ar, dict):
            raise RuntimeError(f"{name}: invalid Arabic record")

        for field, value in patch.items():
            if ar.get(field) != value:
                ar[field] = value
                changed_fields += 1

        achievements = ar.get("achievements")
        key_facts = ar.get("key_facts")
        if not isinstance(achievements, list) or len(achievements) < 3:
            raise RuntimeError(f"{name}: achievements quality check failed")
        if not isinstance(key_facts, list) or len(key_facts) < 3:
            raise RuntimeError(f"{name}: key_facts quality check failed")

    JSON_PATH.write_text(
        json.dumps(data, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    rebuild_js(data)

    if load_js_semantics() != data:
        raise RuntimeError("JSON↔JS semantic equality FAILED")

    print(
        f"Arabic Batch 07 applied: {len(BATCH)} people, "
        f"{changed_fields} field changes."
    )
    print("JSON↔JS semantic equality: PASS")
    print(f"Backup JSON: {json_backup}")
    print(f"Backup JS:   {js_backup}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
